use xiom.io;

fn set_difference(a_set: &Set[Str], b_set: &Set[Str], a_items: &Vec[Str]) -> Vec[Str] {
  let result: Vec[Str] = Vec[Str].new();
  let i = 0;
  while i < a_items.len() {
    let item = match a_items.get(i) { Some(v) => v, None => "" };
    if !b_set.contains(&item) {
      result.push(item);
    }
    i = i + 1;
  }
  return result;
}

fn set_intersection(a_set: &Set[Str], b_set: &Set[Str], a_items: &Vec[Str]) -> Vec[Str] {
  let result: Vec[Str] = Vec[Str].new();
  let i = 0;
  while i < a_items.len() {
    let item = match a_items.get(i) { Some(v) => v, None => "" };
    if b_set.contains(&item) {
      result.push(item);
    }
    i = i + 1;
  }
  return result;
}

